using System;using System.Linq;using System.IO;using System.Security.Cryptography;using System.Text;using Outbreak.Core;using Outbreak.Contracts;using Outbreak.Persistence;
public static partial class Program
{
    private static World HouseholdFixture(HouseholdFurnitureKind kind=HouseholdFurnitureKind.Chair,int hunger=10,int spent=50,int x=5,int y=5)
    {
        var saved=EncounterScenarios.HouseholdLifeTest().Capture();saved.actors=new[]{saved.actors[0]};saved.actors[0].x=x;saved.actors[0].y=y;saved.actors[0].shelterId=saved.actors[0].assignedHouseId;saved.actors[0].shelterX=x;saved.actors[0].shelterY=y;saved.actors[0].shelterState=ShelterState.Inside;saved.actors[0].hunger=hunger;saved.actors[0].energySpent=spent;saved.actors[0].carriedFood=1;saved.actors[0].happiness=0;saved.map.householdFurniture=new[]{new HouseholdFurnitureDocument{x=5,y=5,kind=kind}};return World.Restore(saved);
    }
    private static void CheckHouseholdLifeCases()
    {
        Check("Typed household furniture roundtrips canonically and table composites are atomic",()=>{
            World w=EncounterScenarios.HouseholdLifeTest();Require(w.HouseholdActivitiesAvailable && w.Capture().map.schemaVersion==15 && w.HouseholdFurnitureSites().Length==10,"Household preview missing typed objects.");Require(State(w)==State(EncounterScenarios.HouseholdLifeTest()) && State(w)==State(Documents.ParseSave(State(w))),"Furniture setup failed deterministic saving.");var map=new WorldMap(12,12);for(int y=1;y<11;y++)for(int x=1;x<11;x++)map.Set(x,y,Terrain.Floor);string before=Documents.Encode(map.Capture());Reject(()=>map.SetKitchenTableWithChairs(1,1));Require(before==Documents.Encode(map.Capture()),"Composite partially wrote an invalid chair.");map.SetKitchenTableWithChairs(5,5);Require(!map.CanWalk(5,5) && map.CanWalk(4,5),"Table and chair collision are indistinguishable.");var copy=map.FurnitureAt(5,5);copy.kind=HouseholdFurnitureKind.Bed;Require(!map.CanWalk(5,5),"Furniture read exposed mutable state.");Reject(()=>map.SetFurniture(new HouseholdFurnitureDocument{x=5,y=5,kind=HouseholdFurnitureKind.Radio}));Reject(()=>map.SetFurniture(new HouseholdFurnitureDocument{x=8,y=8,kind=HouseholdFurnitureKind.Chair,working=true}));Reject(()=>map.SetShelf(4,5,4));Reject(()=>map.SetPhone(4,5));Reject(()=>map.SetWeapon(4,5,MeleeWeapon.Bat));
        });
        Check("Snacks consume a whole food item anywhere with endurance-bounded one-to-five relief",()=>{
            foreach(int endurance in new[]{0,5,10}){var saved=HouseholdFixture(hunger:60).Capture();saved.actors[0].x=24;saved.actors[0].y=17;saved.actors[0].shelterId=0;saved.actors[0].shelterX=0;saved.actors[0].shelterY=0;saved.actors[0].shelterState=ShelterState.None;saved.actors[0].endurance=endurance;World w=World.Restore(saved);int initial=w.FoodSupplies().RemainingMeals;w.Step();var a=w.ActorAt(0);Require(a.carriedFood==0 && a.hunger==60-(1+4*endurance/10) && a.householdActivity==HouseholdActivity.Snack && w.FoodSupplies().RemainingMeals==initial-1,"Snack cost or endurance relief changed.");}
        });
        Check("A visible table chair receives a paid approach and one real full meal",()=>{
            var saved=HouseholdFixture(hunger:60,x:4,y:5).Capture();saved.map.householdFurniture=new[]{new HouseholdFurnitureDocument{x=5,y=5,kind=HouseholdFurnitureKind.Chair},new HouseholdFurnitureDocument{x=6,y=5,kind=HouseholdFurnitureKind.KitchenTable}};World w=World.Restore(saved);int food=w.FoodSupplies().RemainingMeals;w.Step();Require(w.ActorAt(0).x==5 && w.ActorAt(0).carriedFood==1 && w.ActorAt(0).energySpent==51,"Table approach teleported, ate early or ignored movement cost.");World copy=Documents.ParseSave(State(w));Run(w,5);Run(copy,5);Require(State(w)==State(copy) && w.ActorAt(0).carriedFood==0 && w.ActorAt(0).hunger==10 && w.FoodSupplies().RemainingMeals==food-1,"A table meal failed physical consumption or exact route replay.");
        });
        Check("Chairs couches and beds give distinct energy recovery without intrinsic media happiness",()=>{
            foreach(var kind in new[]{HouseholdFurnitureKind.Chair,HouseholdFurnitureKind.Couch,HouseholdFurnitureKind.Bed}){World w=HouseholdFixture(kind);w.Step();int expected=kind==HouseholdFurnitureKind.Chair?3:kind==HouseholdFurnitureKind.Couch?6:12;Require(w.ActorAt(0).energySpent==50-expected && w.ActorAt(0).hunger==11 && w.RestingAtFurniture(0),"Wrong furniture recovery rate or missing physical rest.");Require(w.HappinessKnownBy(0).MediaContribution==0,"Furniture itself granted media happiness.");}
        });
        Check("A small chair break stays local while exhaustion justifies a nearby faster bed",()=>{
            var saved=HouseholdFixture(spent:3).Capture();saved.map.householdFurniture=new[]{new HouseholdFurnitureDocument{x=5,y=5,kind=HouseholdFurnitureKind.Chair},new HouseholdFurnitureDocument{x=7,y=5,kind=HouseholdFurnitureKind.Bed}};World w=World.Restore(saved);w.Step();Require(w.ActorAt(0).x==5 && w.ActorAt(0).energySpent==0 && w.RestingAtFurniture(0),"Minor fatigue caused a needless bed detour.");saved=HouseholdFixture(spent:90).Capture();saved.map.householdFurniture=new[]{new HouseholdFurnitureDocument{x=5,y=5,kind=HouseholdFurnitureKind.Chair},new HouseholdFurnitureDocument{x=7,y=5,kind=HouseholdFurnitureKind.Bed}};w=World.Restore(saved);w.Step();var a=w.ActorAt(0);Require((a.x!=5 || a.y!=5) && a.shelterX==7 && a.shelterY==5 && a.energySpent==90+Math.Abs(a.x-5)+Math.Abs(a.y-5),"Exhaustion failed to choose the faster nearby bed with paid travel.");
        });
        Check("Furniture healing pays the existing hunger cost and hungry empty residents can recover without healing",()=>{
            var saved=HouseholdFixture(spent:0).Capture();saved.actors[0].health=90;World w=World.Restore(saved);w.Step();Require(w.ActorAt(0).health==92 && w.ActorAt(0).energySpent==0 && w.ActorAt(0).hunger==11,"Seated healing became free or changed the existing healing amount.");saved=HouseholdFixture(hunger:80,spent:100).Capture();saved.actors[0].carriedFood=0;saved.actors[0].health=90;saved.map.storageBoxes[0].items=new ItemStackDocument[0];w=World.Restore(saved);w.Step();Require(w.ActorAt(0).energySpent==97 && w.ActorAt(0).health==90 && w.ActorAt(0).hunger==81,"Empty-home furniture recovery healed starvation or lost its paid recovery exchange.");
        });
        Check("Personally visible food prevents a hungry resident replacing food seeking with furniture recovery",()=>{
            var saved=HouseholdFixture(hunger:80,spent:100).Capture();saved.actors[0].carriedFood=0;World w=World.Restore(saved);w.Step();Require(!w.RestingAtFurniture(0) && w.ActorAt(0).energySpent==100,"A visible stocked pantry was ignored for a furniture break.");
        });
        Check("Standing idle never regains or spends energy in household mode",()=>{
            var saved=HouseholdFixture(spent:40,x:9,y:9).Capture();saved.map.storageBoxes=null;World w=World.Restore(saved);bool idle=false;for(int t=0;t<20;t++){var before=w.ActorAt(0);w.Step();var after=w.ActorAt(0);if(before.x==after.x && before.y==after.y){idle=true;Require(after.energySpent==before.energySpent,"Standing idle regained or spent energy.");}}Require(idle,"Idle observation never occurred.");
        });
        Check("Media requires working devices and television requires actual seated rest and visibility",()=>{
            var saved=HouseholdFixture(HouseholdFurnitureKind.Couch).Capture();saved.map.householdFurniture=new[]{new HouseholdFurnitureDocument{x=5,y=5,kind=HouseholdFurnitureKind.Couch},new HouseholdFurnitureDocument{x=5,y=3,kind=HouseholdFurnitureKind.Television,working=true},new HouseholdFurnitureDocument{x=8,y=5,kind=HouseholdFurnitureKind.Radio,working=true}};World w=World.Restore(saved);Require(w.HappinessKnownBy(0).MediaContribution==2,"Standing/seated-without-rest watching granted TV mood.");w.Step();Require(w.HappinessKnownBy(0).MediaContribution==4,"Resting TV viewer missed working media.");string before=State(w);for(int i=0;i<5;i++)w.HappinessKnownBy(0);Require(State(w)==before,"Mood inspection advanced the simulation.");Require(w.TrySetApplianceWorking(5,3,false) && w.HappinessKnownBy(0).MediaContribution==2,"Off TV still contributed.");w.TrySetApplianceWorking(8,5,false);Require(w.HappinessKnownBy(0).MediaContribution==0,"Off radio still contributed.");w.TrySetApplianceWorking(5,3,true);w.TrySetApplianceWorking(8,5,true);saved=w.Capture();var map=WorldMap.Restore(saved.map);map.Set(5,4,Terrain.Wall);map.Set(6,5,Terrain.Wall);saved.map=map.Capture();w=World.Restore(saved);Require(w.HappinessKnownBy(0).MediaContribution==2,"TV ignored a wall or nearby radio incorrectly required TV visibility.");Require(!w.TrySetApplianceWorking(5,5,true),"Couch accepted appliance state.");
        });
        Check("Household preferences restore social outdoor park mood and introvert indoor solitude mood",()=>{
            var saved=HouseholdFixture(spent:0).Capture();saved.actors[0].charisma=2;World intro=World.Restore(saved);Require(intro.HappinessKnownBy(0).Change==2,"Introvert indoor solitude recovery missing.");saved.actors[0].charisma=8;World social=World.Restore(saved);Require(social.HappinessKnownBy(0).Change==0,"Unwanted indoor solitude recovered a social actor by itself.");saved.actors[0].x=24;saved.actors[0].y=17;saved.actors[0].shelterId=0;saved.actors[0].shelterX=0;saved.actors[0].shelterY=0;saved.actors[0].shelterState=ShelterState.None;social=World.Restore(saved);Require(social.HappinessKnownBy(0).Change==2,"Known park failed to accelerate outdoor recovery.");saved.actors[0].x=29;saved.actors[0].y=20;social=World.Restore(saved);Require(social.HappinessKnownBy(0).Change==1,"Ordinary outdoors did not restore social mood.");saved.actors[0].charisma=2;intro=World.Restore(saved);Require(intro.HappinessKnownBy(0).Change==1,"Outdoor solitude failed to restore an introvert.");
        });
        Check("Household seat occupancy and activity clocks reject corrupt saves and keep old113 continuation",()=>{
            World w=HouseholdFixture();int id;Require(!w.TrySpawn(Species.Human,5,5,out id),"Multiple residents stacked on one furniture seat.");var saved=w.Capture();saved.rulesVersion=EncounterRules.StoreEntryFlowVersion;Reject(()=>World.Restore(saved));saved=w.Capture();saved.actors[0].householdActivity=HouseholdActivity.Resting;saved.actors[0].householdActivityTick=1;Reject(()=>World.Restore(saved));var map=saved.map;map.schemaVersion=14;Reject(()=>WorldMap.Restore(map));
            string raw=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Fixtures","shopping111-initial.json")).Replace("encounter-prototype-111","encounter-prototype-113");World old=Documents.ParseSave(raw);Run(old,1000);Require(Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(State(old))))=="9699680BB3B82D9F8F2C2CB5AD8AA21C3CBDBDE4224284E5D301ED52E281AD7D","Independent113 continuation changed.");
        });
    }
}
